L2:		KERNEL_INNER: for(n = 0; n < COLS; n++){
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
			min = dst[n];

			if(n > 0){
				min = MIN(min,dst[n-1]);
			}

			if(n < COLS-1){
