L7:	int32_t wall2[COLS * TILE_SIZE];
#pragma HLS array_partition variable=wall2 type=auto{_ARRAY_T_L7} factor=auto{_ARRAY_F_L7} dim=auto{_ARRAY_D_L7}

	memcpy(dst,J,sizeof(int32_t) * COLS);
