void last_step_scan(int bucket[BUCKETSIZE], int sum[SCAN_RADIX])
{
    int radixID, i, bucket_indx;
L4:    last_1:for (radixID=0; radixID<SCAN_RADIX; radixID++) {
#pragma HLS pipeline II=auto{_PIPE_L4}
